// Which look the admin wears. 'figma' = the light, Figma-style look (adminFigmaLook.css, generated by
// scripts/gen-admin-figma-look.py); '' = the original dark purple. The choice is remembered on this
// computer: /admin?look=off goes back to the dark look, ?look=figma returns to the light one.
// Light is the default since 2026-11-28 (checked live on Calls, Directory, Loans, Risk, account page).

const LOOK_KEY = 'moodeng_admin_look';
const HTML_CLASS = 'admin-figma';
// What an admin who never chose gets.
export const DEFAULT_ADMIN_LOOK: AdminLook = 'figma';

export type AdminLook = 'figma' | '';

export function readAdminLook(): AdminLook {
   try {
      const fromLink = new URLSearchParams(window.location.search).get('look');
      if (fromLink === 'figma' || fromLink === 'off') window.localStorage.setItem(LOOK_KEY, fromLink);
      const saved = window.localStorage.getItem(LOOK_KEY);
      if (saved === 'figma') return 'figma';
      if (saved === 'off') return '';
   } catch {
      // Private mode: fall through to the default.
   }
   return DEFAULT_ADMIN_LOOK;
}

/** Put the look on <html> while an admin page is open; returns the undo for when it closes. */
export function applyAdminLook(): () => void {
   const on = readAdminLook() === 'figma';
   document.documentElement.classList.toggle(HTML_CLASS, on);
   return () => document.documentElement.classList.remove(HTML_CLASS);
}
